    UUID principal(String name,List<String> permissions){UUID id=UUID.randomUUID(),role=UUID.randomUUID();db.update("INSERT INTO identity_principal(id,realm,login_name,password_hash,mfa_secret_ciphertext) VALUES (?,'ADMIN',?,?,?)",id,name,passwordHash,crypto.encrypt(MFA));db.update("INSERT INTO role(id,scope_type,code,name) VALUES (?,'ADMIN',?,?)",role,name,name);for(String permission:permissions)db.update("INSERT INTO role_permission SELECT ?,id FROM permission WHERE code=?",role,permission);db.update("INSERT INTO principal_role VALUES (?,?,'ADMIN')",id,role);return id;}
    String session(UUID principal){UUID id=UUID.randomUUID();String token=crypto.token();db.update("INSERT INTO auth_session(id,principal_id,access_token_hash,device_id,expires_at,refresh_expires_at,created_at) VALUES (?,?,?,'SEARCH-TEST',?,?,?)",id,principal,crypto.hash(token),Timestamp.from(clock.instant().plusSeconds(3600)),Timestamp.from(clock.instant().plusSeconds(2592000)),Timestamp.from(clock.instant()));return token;}
    record Response(int status,JsonNode body){JsonNode data(){return body.get("data");}}
    Response call(String method,String path,Object body,String token,Map<String,String> headers){try{var b=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1"+path)).timeout(Duration.ofSeconds(15));if(token!=null)b.header("Authorization","Bearer "+token);headers.forEach(b::header);if(body==null)b.method(method,HttpRequest.BodyPublishers.noBody());else b.header("Content-Type","application/json").method(method,HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body)));var response=http.send(b.build(),HttpResponse.BodyHandlers.ofString());var data=json.readTree(response.body());var safe=json.readTree(response.body());if(safe.has("data")&&safe.get("data").has("reverify_token"))((tools.jackson.databind.node.ObjectNode)safe.get("data")).put("reverify_token","A".repeat(43));SAMPLES.add(Map.of("method",method.toLowerCase(),"path",path,"status",response.statusCode(),"response",safe));return new Response(response.statusCode(),data);}catch(Exception e){throw new AssertionError(path,e);}}
    Response call(String method,String path,Object body,String token){return call(method,path,body,token,Map.of());}
    String proof(String action){clock.value=clock.value.plusSeconds(60);var result=call("POST","/admin/auth/reverify",Map.of("action",action,"password",STAFF_PASSWORD,"totp_code",crypto.totp(MFA,clock.instant().getEpochSecond()/30)),adminToken);assertEquals(200,result.status(),result.body().toString());return result.data().get("reverify_token").asString();}
    Response command(String kind,String reason,String proof,String key){return call("POST","/admin/operations/search/"+kind,Map.of("reason_code",reason),adminToken,Map.of("X-Reverify-Token",proof,"Idempotency-Key",key));}
    CatalogSearchSource.Product product(UUID sku,long price){return new CatalogSearchSource.Product(UUID.nameUUIDFromBytes("TEST SPU".getBytes()),sku,"TEST Brand","CAT","ADULT","DRY",List.of("CHICKEN"),price,true,2,Instant.parse("2026-10-03T00:00:00Z"));}
    CatalogSearchSource.Change change(UUID sku,long price,String type){return source.change(product(sku,price),false,type,UUID.randomUUID().toString());}
    GetResponse next(String queue) throws Exception {final GetResponse[] value={null};await().atMost(Duration.ofSeconds(5)).until(()->{value[0]=channel.basicGet(queue,false);return value[0]!=null;});return value[0];}
    void receive() throws Exception {var value=next(RabbitTopology.SEARCH_QUEUE);var p=new org.springframework.amqp.core.MessageProperties();p.setMessageId(value.getProps().getMessageId());p.setDeliveryTag(value.getEnvelope().getDeliveryTag());listener.receive(new org.springframework.amqp.core.Message(value.getBody(),p),channel);}
    void pump() throws Exception {for(int i=0;i<40&&publisher.publishOne();i++){}while(channel.queueDeclarePassive(RabbitTopology.SEARCH_QUEUE).getMessageCount()>0)receive();while(sync.runOne()){} }
    Map<String,Object> doc(UUID sku){os.refresh(aliases.current());return os.documents(aliases.current()).get(sku);}
    void syncChange(UUID sku,long price) throws Exception {change(sku,price,"CatalogPublished");pump();assertNotNull(doc(sku));}
    @AfterEach void close() throws Exception {RABBIT_PROXY.recover();PROXY.recover();if(channel!=null&&channel.isOpen())channel.close();if(connection!=null&&connection.isOpen())connection.close();}
    @AfterAll static void finish() throws Exception {Files.writeString(Path.of("target/m34-search-contract-samples.json"),JsonMapper.builder().build().writeValueAsString(SAMPLES));RABBIT_PROXY.close();PROXY.close();PG.close();}


