 void catalogFixture(){sku=UUID.randomUUID();spu=UUID.randomUUID();standard=UUID.randomUUID();merchant=UUID.randomUUID();offer=UUID.randomUUID();UUID brand=UUID.randomUUID();db.update("INSERT INTO brands(id,name,source_ref) VALUES (?,?,'TEST source')",brand,"TEST real "+sku);db.update("INSERT INTO spus(id,brand_id,name,pet_category,category) VALUES (?,?,'TEST food','CAT','DRY_FOOD')",spu,brand);db.update("INSERT INTO skus(id,spu_id,sku_code,weight_g,package_unit) VALUES (?,?,?,1000,'BAG')",sku,spu,"TEST "+sku);db.update("INSERT INTO sku_standard_versions(id,sku_id,version_no,status,ingredients,nutrients,allergens_known,life_stage_ids,source_refs,source_updated_on,created_by,published_at) VALUES (?,?,1,'PUBLISHED','[\"TEST ingredient\"]','[]',false,'[]','[\"TEST source\"]','2026-10-01',?,clock_timestamp())",standard,sku,adminId);db.update("INSERT INTO merchant VALUES (?,'TEST real merchant','ACTIVE')",merchant);db.update("INSERT INTO offers(id,merchant_id,sku_id,sale_price_fen,fulfillment_sla,sale_status) VALUES (?,?,?,1400,'TEST 48h','ACTIVE')",offer,merchant,sku);db.update("INSERT INTO inventory_balances(offer_id,on_hand_qty) VALUES (?,7)",offer);}
 EventEnvelope fact(String type){UUID id=UUID.randomUUID();Map<String,Object> payload=type.equals("CatalogStandardPublished")?Map.of("sku_id",sku.toString(),"standard_version_id",standard.toString()):Map.of("offer_id",offer.toString(),"sku_id",sku.toString(),"version",0);return new EventEnvelope(id,type,1,type.equals("CatalogStandardPublished")?"CATALOG_SKU":"OFFER",type.equals("CatalogStandardPublished")?sku.toString():offer.toString(),null,1,0,payload);}
 void send(EventEnvelope e)throws Exception{channel.confirmSelect();channel.basicPublish(RabbitTopology.EXCHANGE,e.event_type(),new AMQP.BasicProperties.Builder().messageId(e.event_id().toString()).deliveryMode(2).build(),json.writeValueAsBytes(e));channel.waitForConfirmsOrDie(3000);}
 void receiveFact(String queue)throws Exception{var value=next(queue);var p=new org.springframework.amqp.core.MessageProperties();p.setMessageId(value.getProps().getMessageId());p.setDeliveryTag(value.getEnvelope().getDeliveryTag());factListener.receive(new org.springframework.amqp.core.Message(value.getBody(),p),channel);}
